"""Consolidated TIFRS cash flows from official SEC 6-K statements (NTD thousands).

Keep cash after taxes, gross PPE acquisition payments and comparative vintages.
Never use parent-company-only statements or the pre-tax cash-generated subtotal.
"""
import calendar
import hashlib
import re
from datetime import date
from .models import Fact
from .inline import InlineParser

LABELS = {
    'Net cash generated by operating activities': 'ocf',
    'Net cash used in investing activities': 'icf',
    'Net cash generated by investing activities': 'icf',
    'Net cash used in financing activities': 'financing_cf',
    'Net cash generated by financing activities': 'financing_cf',
    'Net cash generated by (used in) financing activities': 'financing_cf',
    'Payments for acquisition of property, plant and equipment': 'capex',
    'Share-based compensation': 'sbc',
}


def statement_tables(content):
    parser=InlineParser();parser.feed(content.decode())
    text=' '.join(parser.root.text().split())
    return {'intro':text[:1000], 'unit_evidence':[text[max(0,m.start()-80):m.end()+100] for m in list(re.finditer('Thousands of New Taiwan Dollars',text,re.I))[:3]],
        'tables':[[[' '.join(c.text().split()) for c in row.children if c.tag in {'td','th'}] for row in t.walk('tr')] for t in parser.root.walk('table')]}


def parse_statement(doc):
    intro=doc.get('intro','').lower()
    if 'consolidated' not in intro or 'parent company only' in intro:return []
    if not any('thousands of new taiwan dollars' in s.lower() for s in doc.get('unit_evidence',[])):
        raise ValueError('TIFRS cash statement requires explicit NTD thousands evidence')
    result=[]
    for table in doc['tables']:
        if not isinstance(table,list):continue
        text=' '.join(' '.join(row) for row in table)
        if not any(label in text for label in LABELS):continue
        header=' '.join(' '.join(row) for row in table[:5])
        match=re.search(r'(Three|Six|Nine) Months Ended (March 31|June 30|September 30)',header)
        month={'Three':3,'Six':6,'Nine':9}[match[1]] if match else 12
        years=[]
        for row in table[:5]:
            values=[int(c) for c in row if re.fullmatch(r'20\d{2}',c)]
            if len(values)==2:years=values;break
        if len(years)!=2:raise ValueError('Missing comparative cash flow years')
        for row in table:
            label=next((c for c in row if c in LABELS),None)
            if not label:continue
            numeric=' '.join(row[row.index(label)+1:]).replace('$','').replace(',','')
            tokens=re.findall(r'\(\s*\d+\s*\)|-?\d+|[–—-]',numeric)
            if re.sub(r'\s+','',''.join(tokens))!=re.sub(r'\s+','',numeric):raise ValueError('Unrecognized cash amount')
            values=[0 if c in {'-','–','—'} else -int(c[1:-1]) if c.startswith('(') else int(c) for c in tokens]
            if len(values)!=2:raise ValueError(f'Ambiguous cash flow columns: {label}: {values}')
            for year,value in zip(years,values):
                result.append(Fact(metric=LABELS[label],value=value*1000,unit='TWD',start=date(year,1,1),end=date(year,month,calendar.monthrange(year,month)[1]),
                    filed=doc['filed'],accession=doc['accession'],tag='disclosure:tsm.tifrs.'+LABELS[label],basis='TIFRS',reporting_basis='TIFRS',report_fiscal_year=years[0],
                    source=doc['source'],form='6-K',lineage=[label,'Consolidated TIFRS; NTD thousands × 1000', 'Original document SHA256: '+doc['sha256']]))
    unique={}
    for f in result:
        key=(f.metric,f.start,f.end)
        if key in unique and unique[key].value!=f.value:raise ValueError('Conflicting statement tables')
        unique[key]=f
    return list(unique.values())


def fetch_cashflows(client):
    from .history import filings
    r=filings(client,'0001046179');facts=[]
    for i,form in enumerate(r['form']):
        primary=r['primaryDocument'][i]
        if form!='6-K' or not ('fsx' in primary or re.fullmatch(r'tsm-6k_(?:2022(?:02|05|08|11)|202302)\d{2}\.htm',primary)):continue
        acc=r['accessionNumber'][i];base=f"https://www.sec.gov/Archives/edgar/data/1046179/{acc.replace('-','')}/"
        for item in client.get_json(base+'index.json')['directory']['item']:
            name=item['name']
            if not name.endswith('.htm') or name==primary or name.startswith('R'):continue
            content=client.get_bytes(base+name)
            facts+=parse_statement({**statement_tables(content),'source':base+name,'filed':r['filingDate'][i],'accession':acc,'sha256':hashlib.sha256(content).hexdigest()})
    return facts
